function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
function colLetter(i) { let n = i + 1, out = ''; while (n > 0) { const m = (n - 1) % 26; out = String.fromCharCode(65 + m) + out; n = Math.floor((n - 1) / 26); } return out; }
const hdr = (($('GET INV header').first().json.values || [[]])[0] || []).map(s);
const rows = $input.all().map(function (i) { return i.json; });
if (rows.length < 220) { throw new Error('ABORT: INVESTORS only ' + rows.length); }
const COL = {}; for (const h of ['contact_person', 'email', 'cc', 'sector', 'stage', 'cheque_inr_cr']) { const i = hdr.indexOf(h); if (i < 0) { throw new Error('ABORT: column missing ' + h); } COL[h] = colLetter(i); }
// values from the team info sheet (NewInvestorsFromInfoSheet, 11 Sep 17:03); spelling tidied; blank cells only
const FILL = {
  arganglobal: { cheque_inr_cr: 'USD 100K-500K' },
  shecapital: { sector: 'Women founders only - technology and innovation', stage: 'Seed to Series B', cheque_inr_cr: '$500K to $2M' },
  merakventures: { sector: 'Sector agnostic (B2B, emerging tech)', stage: 'Pre-seed, Seed, Pre-Series A', cheque_inr_cr: '$250K to $3M' },
  capinity: { email: 'sameer@capinity.in', cc: 'deep@capinity.in', contact_person: 'Sameer', sector: 'Sector agnostic', stage: 'Early growth', cheque_inr_cr: 'INR 0.5-10 Cr' },
  capwise: { email: 'rishabh.rathi@capwisefin.com', contact_person: 'Rishabh Rathi', stage: 'Seed to Pre-Series A (venture debt)', cheque_inr_cr: 'INR 5-50 Cr' },
  epsilonxcapital: { email: 'susheel@epsilonxcapital.com', cc: 'swayam@epsilonxcapital.com, vikas@epsilonxcapital.com', contact_person: 'Susheel', stage: 'Growth (structured debt)', cheque_inr_cr: 'INR 20-100 Cr' },
  tatacapital: { sector: 'Financial services, business lending', stage: 'Growth, Late', cheque_inr_cr: 'INR 30-200 Cr' }
};
const byName = {}; for (const r of rows) { const k = nz(r.investor); if (k) { (byName[k] = byName[k] || []).push(r); } }
const NOTE = /meeting|deals shared|she say/i;
const data = [], log = [], kept = [], notFound = [];
for (const k of Object.keys(FILL)) { const rs = byName[k] || []; if (!rs.length) { notFound.push(k); continue; }
  for (const r of rs) { for (const f of Object.keys(FILL[k])) { const cur = s(r[f]);
    if (cur && !NOTE.test(cur)) { kept.push(s(r.investor) + '.' + f + ' kept: ' + cur.slice(0, 40)); continue; }
    data.push({ range: 'INVESTORS!' + COL[f] + r.row_number, values: [[FILL[k][f]]] }); log.push({ investor: s(r.investor), row: r.row_number, field: f, value: FILL[k][f] }); } } }
if (notFound.length) { throw new Error('ABORT: not found in INVESTORS: ' + notFound.join(', ')); }
if (!data.length) { throw new Error('ABORT: nothing to fill'); }
return [{ json: { writes: data.length, data: data, log: log, kept: kept } }];

function s(v) { return String(v == null ? '' : v).trim(); }
const plan = $('Plan').first().json;
const after = $input.all().map(function (i) { return i.json; });
const byRow = {}; for (const r of after) { byRow[r.row_number] = r; }
const bad = plan.log.filter(function (l) { return s((byRow[l.row] || {})[l.field]) !== l.value; }).map(function (l) { return l.investor + '.' + l.field; });
return [{ json: { writes: plan.writes, not_applied: bad, kept_existing: plan.kept, ok: bad.length === 0 } }];
